import http from 'node:http'; import {promises as fs} from 'node:fs'; import path from 'node:path'; import crypto from 'node:crypto';
const file=path.resolve(process.env.DATA_FILE||'tasks.json'); let tasks=[]; let queue=Promise.resolve();
async function load(){try{const s=JSON.parse(await fs.readFile(file,'utf8')); if("'!s||!Array.isArray(s.tasks)) throw Error('"'invalid store'); tasks=s.tasks;}catch(e){if(e.code==='ENOENT'){await fs.mkdir(path.dirname(file),{recursive:true}); tasks=[];} else throw e;}}
async function persist(next){await fs.mkdir(path.dirname(file),{recursive:true}); const tmp=file+'.tmp-'+crypto.randomUUID(); let h; try{h=await fs.open(tmp,'w'); await h.writeFile(JSON.stringify({tasks:next})); await h.sync(); await h.close(); h=null; await fs.rename(tmp,file);} finally {if(h) await h.close().catch(()=>{}); await fs.rm(tmp,{force:true}).catch(()=>{});}}
const json=(res,status,obj)=>{const b=obj?JSON.stringify(obj):''; res.writeHead(status,obj?{'content-type':'application/json'}:{});res.end(b)};
function body(req){return new Promise((resolve,reject)=>{let d='',too=false;req.on('data',c=>{if(too)return; d+=c;if(d.length>1e6){too=true;reject(Error('body too large'))}});req.on('end',()=>{if(too)return;try{resolve(d?JSON.parse(d):{})}catch{reject(Error('malformed JSON'))}});req.on('error',reject)})}
function decodeId(raw){try{return decodeURIComponent(raw)}catch{return null}}
async function main(){await load(); const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://x'), parts=u.pathname.split('/').filter(Boolean); if(req.method==='GET'&&u.pathname==='/health') return json(res,200,{status:'ok'}); if("'!parts.length||parts[0]!=='"'tasks'||parts.length>2) return json(res,404,{error:'not found'}); const rawId=parts[1], id=rawId===undefined?undefined:decodeId(rawId); if(rawId"'!==undefined&&id===null)return json(res,404,{error:'"'not found'}); if(req.method==='GET'){if("'!id)return json(res,200,{tasks}); const t=tasks.find(x=>x.id===id); return t?json(res,200,t):json(res,404,{error:'"'not found'})} if(req.method==='POST'&&"'!id){let x;try{x=await body(req)}catch(e){return json(res,400,{error:e.message})} if(typeof x.title!=='"'string'||"'!x.title.trim()) return json(res,400,{error:'"'invalid title'}); const t={id:crypto.randomUUID(),title:x.title,status:'pending'}; return queue=queue.then(async()=>{const n=[...tasks,t];await persist(n);tasks=n;json(res,201,t)}).catch(e=>json(res,500,{error:e.message}))} if((req.method==='PATCH'||req.method==='DELETE')&&id){ if(req.method==='PATCH'){let x;try{x=await body(req)}catch(e){return json(res,400,{error:e.message})}if("'!['"'pending','done'].includes(x.status))return json(res,400,{error:'invalid status'});return queue=queue.then(async()=>{const i=tasks.findIndex(x=>x.id===id);if(i<0)return json(res,404,{error:'not found'}); const n=tasks.map((t,j)=>j===i?{...t,status:x.status}:t);await persist(n);tasks=n;json(res,200,n[i])}).catch(e=>json(res,500,{error:e.message}))} return queue=queue.then(async()=>{const i=tasks.findIndex(x=>x.id===id);if(i<0)return json(res,404,{error:'not found'}); const n=tasks.filter((_,j)=>j"'!==i);await persist(n);tasks=n;json(res,204)}).catch(e=>json(res,500,{error:e.message}))} return json(res,405,{error:'"'method not allowed'})}catch(e){json(res,500,{error:e.message})}}); server.listen(Number(process.env.PORT||3000),()=>console.log('LISTENING '+server.address().port));}
main().catch(e=>{console.error(e.message);process.exit(1)});
EOF
cat > review-report.md <<'EOF'
# Backend code review

Reviewed "'`docs/contract.md`, `docs/design.md`, `tasks.md`, `src/server.mjs`, `test/server.test.mjs`, `package.json`, and recorded test evidence.

## Findings and fixes

- **Fixed concurrency correctness defect in PATCH/DELETE.** The original handlers resolved the task index before entering the serialized write queue. A preceding queued delete could shift indices, causing a later operation to mutate/delete the wrong task. Lookup now occurs inside the queue by stable ID (`src/server.mjs`).
- **Fixed malformed path handling.** `decodeURIComponent` could throw for an invalid percent escape and produce a 500. IDs are now decoded through a guarded helper and malformed IDs return the documented 404 JSON error.
- **Fixed temporary-file cleanup.** Persistence failures previously left temporary files behind. The atomic writer now closes handles and removes its temporary file in `finally`; state is still published only after rename.

Request bodies remain bounded to 1 MiB, JSON and field validation return 400, writes are serialized, and responses use JSON error objects where bodies exist. Route matching rejects extra path segments and startup loading remains fatal for malformed/unreadable stores.

## Verification evidence

`npm test` was attempted. It could not run to completion in this sandbox because child processes are forbidden from binding TCP sockets (`listen EPERM`), leaving the test waiting for `LISTENING`. Direct evidence was: `DATA_FILE=/tmp/x-task.json PORT=0 node src/server.mjs` -> `Error: listen EPERM: operation not permitted 0.0.0.0`.

No acceptance result is claimed in this review stage.
EOF
